const b=$json.body??$json;
const action=String(b.action??'chat').trim();
const message=String(b.message??'').trim();
const enquiryId=String(b.enquiry_id??'').trim();
const contactId=String(b.contact_id??'').trim();
const serviceSlug=String(b.service_slug??'').trim();
const serviceName=String(b.service_name??'').trim();
const date=String(b.date??'').trim();
const time=String(b.time??'').trim();
const fullName=String(b.full_name??'').trim();
const email=String(b.email??'').trim().toLowerCase();
const sessionId=String(b.session_id??('demo-'+Date.now())).replace(/[^a-zA-Z0-9_-]/g,'').slice(0,80);
let history=[];try{history=JSON.parse(String(b.history??'[]'));if(!Array.isArray(history))history=[]}catch{}
if(!history.length)history=[{who:'assistant',text:'Hi 👋 Welcome to Favfare. What would you like help with today?'}];
function nextMonday(){const x=new Date();const day=x.getUTCDay();let add=(8-day)%7;if(add===0)add=7;x.setUTCDate(x.getUTCDate()+add);return x.toISOString().slice(0,10)}
let api_url,payload;
if(action==='service_selected'){
  api_url='https://n8n-production-806e.up.railway.app/webhook/favfare-demo/quote';
  payload={message:message||('I am interested in '+serviceName),service_slug:serviceSlug,full_name:'WhatsApp Patient',phone:'+2348000000200',whatsapp_id:'favfare-'+sessionId};
}else if(action==='availability'){
  api_url='https://n8n-production-806e.up.railway.app/webhook/favfare-demo/booking';
  payload={action:'availability_for_date',preferred_date:date||nextMonday(),enquiry_id:enquiryId};
}else if(action==='request_booking'){
  api_url='https://n8n-production-806e.up.railway.app/webhook/favfare-demo/booking';
  payload={action:'request_booking',enquiry_id:enquiryId,preferred_date:date,preferred_time:time};
}else if(action==='capture_email'){
  api_url='https://shftukueyostzbyqxmqw.supabase.co/functions/v1/favfare-demo-contact';
  payload={contact_id:contactId,full_name:fullName,phone:'+2348000000200',email};
}else if(action==='booking_status'){
  api_url='https://n8n-production-806e.up.railway.app/webhook/favfare-demo/crm';
  payload={action:'enquiry_detail',enquiry_id:enquiryId};
}else{
  api_url='https://n8n-production-806e.up.railway.app/webhook/favfare-demo/crm';
  payload={action:action==='chat'?'catalogue':'health'};
}
return[{json:{action,message,enquiry_id:enquiryId,contact_id:contactId,service_slug:serviceSlug,service_name:serviceName,date:date||nextMonday(),time,full_name:fullName,email,session_id:sessionId,history,api_url,payload}}];

const d=$json??{};const c=$('Normalize Conversation').first().json;
const esc=(v)=>String(v??'').replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));
let h=Array.isArray(c.history)?[...c.history]:[];const say=(who,text)=>h.push({who,text:String(text)});
const hidden=(n,v)=>'<input type=\"hidden\" name=\"'+esc(n)+'\" value=\"'+esc(v)+'\">';
const effectiveEnquiry=(c.action==='service_selected'&&d.enquiry_id)?String(d.enquiry_id):c.enquiry_id;
const effectiveContact=(c.action==='service_selected'&&d.contact_id)?String(d.contact_id):c.contact_id;
const state=(over={})=>{const s={session_id:c.session_id,enquiry_id:effectiveEnquiry,contact_id:effectiveContact,service_slug:c.service_slug,service_name:c.service_name,date:c.date,time:c.time,full_name:c.full_name,email:c.email,...over};return hidden('history',JSON.stringify(h))+Object.entries(s).map(([k,v])=>hidden(k,v??'')).join('');};
const formButton=(action,label,over={})=>'<form method=\"post\" action=\"/webhook/favfare-demo/patient-action-v3\">'+hidden('action',action)+state(over)+'<button>'+esc(label)+'</button></form>';
const composer=()=>'<form class=\"composer\" method=\"post\" action=\"/webhook/favfare-demo/patient-action-v3\">'+hidden('action','chat')+state()+'<input name=\"message\" placeholder=\"Type a message\" autocomplete=\"off\" required><button>➤</button></form>';
const pretty=(iso)=>{if(!iso)return'';return new Date(iso+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});};
const services=Array.isArray(d.services)?d.services:[];
const bySlug=(s)=>services.find(x=>x.slug===s);
const canQuote=(s)=>s&&s.demo_seed_status==='approved'&&!s.needs_clinic_confirmation&&s.price_display;
const serviceButton=(s)=>{if(!s)return'';return formButton('service_selected',s.name+(canQuote(s)?' · '+s.price_display:''),{service_slug:s.slug,service_name:s.name,message:'I am interested in '+s.name});};
const serviceList=(arr)=>'<div class=\"list\">'+arr.filter(Boolean).map(serviceButton).join('')+'</div>';
const popular=()=>serviceList(['scaling-and-polishing','teeth-whitening-generic','medical-braces','veneers','composite-bonding-broken-tooth','dentures'].map(bySlug));
const crmLink='<a href=\"/webhook/favfare-demo/crm-ui\" target=\"_blank\">Open staff CRM →</a>';
let controls='';let allowComposer=true;

if(c.action==='chat'){
 const m=c.message.toLowerCase();if(c.message)say('patient',c.message);
 if(/pain|swelling|swollen|bleeding|infection|diagnos|medicine|medication|what is wrong/.test(m)){
   say('assistant','I can help with clinic information and booking, but I can’t diagnose symptoms in chat. A Favfare team member should review that with you.');
   controls='<div class=\"quick\">'+formButton('chat','Talk to staff',{message:'I want to speak to a staff member'})+formButton('chat','View services',{message:'Show me your services'})+'</div>';
 }else if(/talk to staff|human|person|someone/.test(m)){
   say('assistant','Of course. I’ll flag this for a person rather than guess. You can still browse services while the team follows up.');
   controls='<div class=\"quick\">'+formButton('chat','View services',{message:'Show me your services'})+'</div>';
 }else if(/clean|cleaning|scale|polish|stain/.test(m)){
   say('assistant','Sure — are you mainly looking for a regular cleaning, or do you have tougher stains you want removed?');
   controls='<div class=\"quick\">'+serviceButton(bySlug('scaling-and-polishing'))+serviceButton(bySlug('tough-stain-removal-scaling-polishing'))+'</div>';
 }else if(/white|whiten|bright/.test(m)){
   say('assistant','Absolutely. Favfare has a few whitening options. I can show them, but I’ll only quote a price when the clinic data is approved and unambiguous.');
   controls=serviceList(services.filter(x=>String(x.slug).includes('whitening')));
 }else if(/service|option|offer|treatment/.test(m)){
   say('assistant','Sure. Here are some popular Favfare services. Pick one and I’ll help with the next step.');controls=popular();
 }else if(/book|appointment|available|schedule/.test(m)){
   say('assistant','Absolutely. Which service would you like to book?');controls=popular();
 }else if(/brace/.test(m)){
   say('assistant','Favfare offers medical braces. I can help you enquire about them, but I won’t guess an unconfirmed price.');controls=serviceList([bySlug('medical-braces')]);
 }else if(/veneer/.test(m)){
   say('assistant','Favfare offers veneer options. Choose one below and I’ll tell you what the clinic data lets me confirm.');controls=serviceList([bySlug('veneers'),bySlug('composite-veneer')]);
 }else if(/chipped|broken|bonding/.test(m)){
   say('assistant','Yes — Favfare has options for chipped or broken teeth. Here are the relevant services.');controls=serviceList([bySlug('chipped-tooth'),bySlug('composite-bonding-broken-tooth')]);
 }else if(/hi|hello|hey|good morning|good afternoon|good evening/.test(m)){
   say('assistant','Hi 👋 What are you looking to improve — cleaning, whitening, fixing a tooth, or something else?');
   controls='<div class=\"quick\">'+formButton('chat','Cleaning',{message:'I want to clean my teeth'})+formButton('chat','Whitening',{message:'I want whiter teeth'})+formButton('chat','Fix a tooth',{message:'I have a chipped tooth'})+formButton('chat','View services',{message:'Show me your services'})+'</div>';
 }else{
   say('assistant','I can help you compare Favfare services, check approved prices, and request an appointment. What are you hoping to improve?');
   controls='<div class=\"quick\">'+formButton('chat','View services',{message:'Show me your services'})+formButton('chat','Book appointment',{message:'I want to book an appointment'})+'</div>';
 }
}else if(c.action==='service_selected'){
 say('patient','I’m interested in '+(c.service_name||'that service')+'.');
 if(d.enquiry_id){
   say('assistant',d.reply||'I found the service. Would you like me to check available times?');
   controls='<div class=\"quick\">'+formButton('availability','Check available times')+formButton('chat','Ask a question',{message:'I have a question about '+c.service_name})+'</div>';
 }else{
   say('assistant','Favfare does offer '+(c.service_name||'that service')+'. The public information isn’t clear enough for me to quote it safely, so I’d rather have the clinic confirm the current price than guess.');
   controls='<div class=\"quick\">'+formButton('chat','Talk to staff',{message:'I want the clinic to confirm the price for '+c.service_name})+formButton('chat','View other services',{message:'Show me your services'})+'</div>';
 }
}else if(c.action==='availability'){
 say('patient','Yes, please check available times.');
 const slots=Array.isArray(d.slots)?d.slots.slice(0,8):[];
 if(slots.length){
   say('assistant','I found these available times for '+pretty(c.date)+'. Which works best for you?');
   controls='<div class=\"slots\">'+slots.map(x=>formButton('choose_time',String(x).slice(0,5),{time:String(x).slice(0,5)})).join('')+'</div>';
 }else{
   say('assistant','I couldn’t find an available demo slot on that date. I can check with the team for another day.');
   controls='<div class=\"quick\">'+formButton('chat','Talk to staff',{message:'Please help me find another appointment day'})+formButton('chat','View services',{message:'Show me your services'})+'</div>';
 }
}else if(c.action==='choose_time'){
 say('patient',c.time);say('assistant','That time is available right now. Before I send the request, what full name should I put on the booking?');
 controls='<form class=\"single\" method=\"post\" action=\"/webhook/favfare-demo/patient-action-v3\">'+hidden('action','capture_name')+state()+'<input name=\"full_name\" placeholder=\"Your full name\" autocomplete=\"name\" required><button>Continue</button></form>';
}else if(c.action==='capture_name'){
 say('patient',c.full_name);say('assistant','Thanks, '+c.full_name+'. What email address should Favfare attach to the booking?');
 controls='<form class=\"single\" method=\"post\" action=\"/webhook/favfare-demo/patient-action-v3\">'+hidden('action','capture_email')+state()+'<input type=\"email\" name=\"email\" placeholder=\"Email address\" autocomplete=\"email\" required><button>Continue</button></form><div class=\"detected\">Your WhatsApp phone number is already captured automatically.</div>';
}else if(c.action==='capture_email'){
 say('patient',c.email);
 if(d.ok){
   say('assistant','Perfect. I have your name, email, and WhatsApp number. Please confirm that you want me to send the appointment request for '+pretty(c.date)+' at '+c.time+'.');
   controls='<div class=\"summary\"><strong>'+esc(c.service_name||'Favfare service')+'</strong><span>'+esc(pretty(c.date))+' · '+esc(c.time)+'</span><span>'+esc(c.full_name)+' · '+esc(c.email)+'</span></div>'+formButton('request_booking','Send appointment request');
 }else{
   say('assistant','I couldn’t save those details just now. Please try the email again.');
   controls='<form class=\"single\" method=\"post\" action=\"/webhook/favfare-demo/patient-action-v3\">'+hidden('action','capture_email')+state()+'<input type=\"email\" name=\"email\" placeholder=\"Email address\" required><button>Try again</button></form>';
 }
}else if(c.action==='request_booking'){
 say('patient','Yes, send the request.');
 if(d.ok){
   say('assistant',d.reply||'Your appointment request has been recorded.');
   say('assistant','A Favfare team member still needs to confirm it. I’ve saved the request in the clinic CRM for staff review.');
   controls='<div class=\"quick\">'+formButton('booking_status','Check booking status')+'</div><div class=\"actions\">'+crmLink+'<a class=\"secondary\" href=\"/webhook/favfare-demo/patient\">Start a new demo</a></div>';
   allowComposer=false;
 }else{
   say('assistant','That slot is no longer available. I can check again for another time.');controls=formButton('availability','Check other times');
 }
}else if(c.action==='booking_status'){
 say('patient','Can you check my booking status?');
 const e=d.enquiry??{};const aps=Array.isArray(d.appointments)?d.appointments:[];const ap=aps.find(x=>['confirmed','held'].includes(x.status))||aps[0]||{};
 const bstat=String(e.booking_status??'');const estat=String(e.status??'');const astat=String(ap.status??'');
 const apDate=ap.appointment_date||e.preferred_date||c.date;const apTime=String(ap.start_time||e.preferred_time_window||c.time||'').slice(0,5);
 if(bstat==='confirmed'||estat==='booked'||astat==='confirmed'){
   say('assistant','Good news — your appointment is confirmed for '+pretty(apDate)+' at '+apTime+'.');
   controls='<div class=\"statuscard confirmed\"><strong>Confirmed</strong><span>'+esc(pretty(apDate))+' · '+esc(apTime)+'</span><span>'+esc(c.service_name||e.service?.name||'Favfare appointment')+'</span></div><div class=\"actions\">'+crmLink+'<a class=\"secondary\" href=\"/webhook/favfare-demo/patient\">New demo</a></div>';
   allowComposer=false;
 }else if(bstat==='proposed'){
   say('assistant','The Favfare team proposed another time: '+pretty(apDate)+' at '+apTime+'. A staff member can help you accept or adjust it.');
   controls='<div class=\"statuscard proposed\"><strong>New time proposed</strong><span>'+esc(pretty(apDate))+' · '+esc(apTime)+'</span></div><div class=\"quick\">'+formButton('booking_status','Check again')+formButton('chat','Talk to staff',{message:'I want to discuss the proposed appointment time'})+'</div>';
 }else if(estat==='closed'){
   say('assistant','This enquiry has been closed by the Favfare team. If you still need help, we can start a new enquiry.');
   controls='<div class=\"actions\"><a class=\"secondary\" href=\"/webhook/favfare-demo/patient\">Start a new enquiry</a></div>';allowComposer=false;
 }else{
   say('assistant','Your appointment request is still waiting for staff confirmation. I’ll keep it marked as pending rather than calling it booked early.');
   controls='<div class=\"statuscard pending\"><strong>Pending confirmation</strong><span>'+esc(pretty(apDate))+' · '+esc(apTime)+'</span></div><div class=\"quick\">'+formButton('booking_status','Check again')+'</div><div class=\"actions\">'+crmLink+'</div>';
   allowComposer=false;
 }
}
const bubbles=h.map(x=>'<div class=\"msg '+(x.who==='patient'?'patient':'assistant')+'\"><div class=\"bubble\">'+esc(x.text)+'</div></div>').join('');
const html='<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Favfare Patient Assistant</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#e7eee9;color:#17241e;min-height:100vh;display:grid;place-items:center;padding:22px}.wrap{width:min(1050px,100%);display:grid;grid-template-columns:1fr 400px;gap:38px;align-items:center}.intro small{font-weight:850;letter-spacing:.14em;color:#426454}.intro h1{font-size:44px;letter-spacing:-.04em;margin:10px 0}.intro p{color:#65716b;line-height:1.7;max-width:560px}.note{background:white;padding:18px;border-radius:18px;margin-top:24px;border:1px solid #d9e3dc}.note span{font-size:12px;color:#6a756f}.back{display:inline-block;margin-top:16px;color:#2e5b49;font-weight:750;text-decoration:none}.phone{height:760px;max-height:90vh;background:#efeae2;border-radius:26px;overflow:hidden;box-shadow:0 24px 70px rgba(16,50,36,.22);display:flex;flex-direction:column}.top{background:#075e54;color:white;padding:14px 16px;display:flex;gap:12px;align-items:center}.avatar{width:42px;height:42px;border-radius:50%;background:white;color:#075e54;display:grid;place-items:center;font-weight:900}.top strong{display:block}.top span{font-size:12px;opacity:.82}.status{font-size:11px;padding:7px 12px;background:#fff7cf;text-align:center;color:#715800}.chat{flex:1;overflow:auto;padding:18px 14px;background-image:radial-gradient(rgba(0,0,0,.025) 1px,transparent 1px);background-size:18px 18px}.msg{display:flex;margin:9px 0}.msg.patient{justify-content:flex-end}.bubble{max-width:84%;padding:10px 12px;border-radius:9px;line-height:1.45;font-size:14px;box-shadow:0 1px 1px rgba(0,0,0,.08)}.assistant .bubble{background:white;border-top-left-radius:2px}.patient .bubble{background:#d9fdd3;border-top-right-radius:2px}.controls{padding:10px;background:#f0f2f5}.quick{display:grid;grid-template-columns:1fr 1fr;gap:7px}.quick form,.slots form,.list form{margin:0}.quick button,.slots button,.list button{width:100%;border:1px solid #a9c7b8;background:white;color:#12624c;padding:10px;border-radius:12px;font-weight:750;cursor:pointer}.list{display:grid;gap:7px}.list button{text-align:left}.slots{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.composer{display:flex;gap:8px;margin-top:8px}.composer input,.single input{flex:1;border:1px solid #d7dfda;border-radius:22px;padding:12px 15px;font-size:14px;outline:none;background:white}.composer button{width:44px;height:44px;border:0;border-radius:50%;background:#00a884;color:white;font-size:18px}.single{display:flex;gap:8px}.single button{border:0;border-radius:12px;padding:0 15px;background:#00a884;color:white;font-weight:800}.detected{font-size:10px;color:#6f7c76;margin-top:6px}.summary,.statuscard{display:grid;gap:4px;background:white;border:1px solid #d7dfda;border-radius:12px;padding:12px;margin-bottom:8px}.summary span,.statuscard span{font-size:12px;color:#66736d}.statuscard.confirmed{border-color:#7fc5a5;background:#f2fff8}.statuscard.pending{border-color:#e0c66f;background:#fffbed}.statuscard.proposed{border-color:#9ab8d6;background:#f4f9ff}.actions{display:grid;gap:8px;margin-top:8px}.actions a{display:block;text-align:center;text-decoration:none;background:#075e54;color:white;padding:11px;border-radius:12px;font-weight:800}.actions .secondary{background:white;color:#075e54;border:1px solid #a9c7b8}@media(max-width:850px){.wrap{grid-template-columns:1fr}.intro h1{font-size:34px}.phone{height:78vh}}</style></head><body><div class=\"wrap\"><section class=\"intro\"><small>BIZI SYSTEMS · LIVE SALES DEMO</small><h1>Favfare Patient Assistant</h1><p>A conversational assistant that moves a patient from first question to a staff-reviewed booking, then reflects the clinic’s decision back into the patient conversation.</p><div class=\"note\"><strong>One shared patient journey</strong><br><span>Patient chat → structured service data → live availability → CRM → staff decision → patient status.</span></div><a class=\"back\" href=\"/webhook/favfare-demo/crm-ui\" target=\"_blank\">Open staff CRM ↗</a></section><section class=\"phone\"><div class=\"top\"><div class=\"avatar\">F</div><div><strong>Favfare The Clinic</strong><span>Patient Assistant · online</span></div></div><div class=\"status\">Demo · WhatsApp number auto-captured · staff confirms bookings</div><div class=\"chat\">'+bubbles+'</div><div class=\"controls\">'+controls+(allowComposer?composer():'')+'</div></section></div></body></html>';
return[{json:{html}}];
